import org.eclipse.jdt.core.dom.ASTMatcher;
import org.eclipse.jdt.core.dom.ITypeBinding;
import org.eclipse.jdt.core.dom.ChildListPropertyDescriptor;
import org.eclipse.jdt.core.dom.StructuralPropertyDescriptor;

// A minimal mock implementation of Statement for compilation within an example.
// In a real JDT environment, org.eclipse.jdt.core.dom.Statement is an abstract class.
abstract class MockStatement extends Statement {
    private int startPosition;
    MockStatement(int start) { super(null); this.startPosition = start; }
    @Override public int getStartPosition() { return startPosition; }
    // Minimal stubs for abstract methods to make it compile
    @Override public int getLength() { return 10; }
    @Override public int getNodeType() { return 0; }
    @Override public AST getAST() { return null; }
    @Override public Object accept(ASTVisitor visitor) { return null; }
    @Override protected void accept0(ASTVisitor visitor) {}
    @Override int internalStructuralPropertiesForType(int apiLevel) { return 0; }
    @Override ASTNode internalGetSetParent(ASTNode parent, boolean set) { return null; }
    @Override ASTNode internalGetSetChildProperty(StructuralPropertyDescriptor property, boolean get, ASTNode child) { return null; }
    @Override List<ASTNode> internalGetSetListProperty(ChildListPropertyDescriptor property, boolean get, List<ASTNode> list) { return null; }
    @Override String internalGetMessage() { return null; }
    @Override public boolean subtreeMatch(ASTMatcher matcher, Object other) { return false; }
    @Override int memFootprint() { return 0; }
    @Override public int getExtendedStartPosition() { return 0; }
    @Override public int getExtendedLength() { return 0; }
    @Override public ITypeBinding resolveTypeBinding() { return null; }
}

public class Example {
    public int findIndex(int offset, List<MockStatement> statements) {
        for (int i = 0; i < statements.size(); i++) {
            MockStatement s = statements.get(i);
            if (offset < s.getStartPosition()) { // Original line from diff
                return i;
            }
            // Other conditions that should not be affected by this specific rule
            if (offset < s.getStartPosition() + s.getLength()) {
                return i;
            }
        }
        return -1;
    }
}

